import { requestAuthHeaders } from "./auth-headers.js";
import { sanitizeMessageRecord } from "./sanitize.js";
import type { MessagingEvent } from "./types.js";
import { errorFromResponse, parseErrorBody } from "./errors.js";
import { buildUrl } from "./http.js";

export function parseSseChunk(chunk: string): MessagingEvent | null {
  const lines = chunk.split("\n");
  let data = "";
  for (const line of lines) {
    if (line.startsWith(":")) continue;
    if (line.startsWith("data:")) {
      data += (data ? "\n" : "") + line.slice(5).trimStart();
    }
  }
  if (!data) return null;
  try {
    return sanitizeMessageRecord(JSON.parse(data) as MessagingEvent);
  } catch {
    return null;
  }
}

export interface ReadStreamOpts {
  baseUrl: string;
  builderApiKey?: string;
  accessToken?: string;
  /** When set, awaited before the stream fetch; returned Bearer wins for that request. */
  getAccessToken?: () => Promise<string | null>;
  alias?: string | undefined;
  fetchImpl: typeof fetch;
  signal?: AbortSignal | undefined;
  onEvent?: (event: MessagingEvent) => void;
  onError?: (err: Error) => void;
}

export function readMessagingEventsStream(opts: ReadStreamOpts): {
  close: () => void;
  done: Promise<void>;
} {
  const controller = new AbortController();
  const signal = opts.signal
    ? AbortSignal.any([opts.signal, controller.signal])
    : controller.signal;

  const url = buildUrl(opts.baseUrl, "/v1/messaging/events", {
    ...(opts.alias ? { alias: opts.alias } : {}),
  });

  const done = (async () => {
    let accessToken = opts.accessToken;
    let builderApiKey = opts.builderApiKey;
    if (opts.getAccessToken) {
      const token = await opts.getAccessToken();
      const trimmed = token?.trim();
      if (trimmed) accessToken = trimmed;
    }

    let res: Response;
    try {
      res = await opts.fetchImpl(url, {
        method: "GET",
        headers: {
          Accept: "text/event-stream",
          ...requestAuthHeaders({
            ...(accessToken !== undefined ? { accessToken } : {}),
            ...(builderApiKey !== undefined ? { builderApiKey } : {}),
          }),
        },
        signal,
      });
    } catch (err) {
      if (signal.aborted) return;
      opts.onError?.(err instanceof Error ? err : new Error(String(err)));
      return;
    }

    if (!res.ok || !res.body) {
      const errBody = parseErrorBody(await res.text());
      const apiErr = errorFromResponse(res.status, errBody);
      opts.onError?.(apiErr);
      return;
    }

    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buf = "";
    try {
      while (true) {
        const { value, done: readerDone } = await reader.read();
        if (readerDone) break;
        buf += decoder.decode(value, { stream: true });
        let idx: number;
        while ((idx = buf.indexOf("\n\n")) >= 0) {
          const chunk = buf.slice(0, idx);
          buf = buf.slice(idx + 2);
          const event = parseSseChunk(chunk);
          if (event !== null) opts.onEvent?.(event);
        }
      }
    } catch (err) {
      if (!signal.aborted) {
        opts.onError?.(err instanceof Error ? err : new Error(String(err)));
      }
    } finally {
      try {
        reader.releaseLock();
      } catch {
        /* ignore */
      }
    }
  })();

  return {
    close: () => controller.abort(),
    done,
  };
}

export async function* streamEvents(
  opts: ReadStreamOpts,
): AsyncGenerator<MessagingEvent, void, undefined> {
  const queue: MessagingEvent[] = [];
  let rejectWait: ((err: Error) => void) | undefined;
  let resolveWait: (() => void) | undefined;
  let closed = false;
  let streamError: Error | undefined;

  const wake = (): void => {
    resolveWait?.();
    resolveWait = undefined;
    rejectWait = undefined;
  };

  const { close, done } = readMessagingEventsStream({
    ...opts,
    onEvent: (ev) => {
      queue.push(ev);
      wake();
    },
    onError: (err) => {
      streamError = err;
      closed = true;
      rejectWait?.(err);
      wake();
    },
  });

  void done.finally(() => {
    closed = true;
    wake();
  });

  if (opts.signal) {
    opts.signal.addEventListener("abort", () => {
      closed = true;
      close();
      wake();
    });
  }

  try {
    while (!closed || queue.length > 0) {
      if (queue.length > 0) {
        yield queue.shift()!;
        continue;
      }
      if (streamError) throw streamError;
      if (closed) break;
      await Promise.race([
        done,
        new Promise<void>((resolve, reject) => {
          resolveWait = resolve;
          rejectWait = reject;
        }),
      ]);
      if (streamError) throw streamError;
      if (closed && queue.length === 0) break;
    }
  } finally {
    close();
    await done.catch(() => undefined);
  }
}
