export interface MindsApiErrorBody {
  error?: { type?: string; subType?: string; message?: string } | string;
  message?: string;
}

export class MindsApiError extends Error {
  readonly status: number;
  readonly code: string;
  readonly requestId?: string | undefined;

  constructor(args: {
    status: number;
    code: string;
    message: string;
    requestId?: string | undefined;
  }) {
    super(args.message);
    this.name = "MindsApiError";
    this.status = args.status;
    this.code = args.code;
    this.requestId = args.requestId;
  }
}

export function parseErrorBody(text: string): MindsApiErrorBody {
  if (!text) return {};
  try {
    return JSON.parse(text) as MindsApiErrorBody;
  } catch {
    return { message: text.slice(0, 500) };
  }
}

export function errorFromResponse(status: number, body: MindsApiErrorBody): MindsApiError {
  let code = "http_error";
  let message = `HTTP ${status}`;

  if (typeof body.error === "object" && body.error !== null) {
    code = body.error.type ?? body.error.subType ?? code;
    message = body.error.message ?? message;
  } else if (typeof body.error === "string") {
    code = body.error;
  }
  if (body.message) message = body.message;

  return new MindsApiError({ status, code, message });
}
