import { BUILDER_API_KEY_HEADER } from "./constants.js";

/** Live credentials for api.build. Access token wins over the Builder API key. */
export type ClientCredentials = {
  accessToken?: string;
  builderApiKey?: string;
};

/** Auth headers for api.build — Bearer when an access token is set, else `X-Api-Key`. */
export function requestAuthHeaders(credentials: ClientCredentials): Record<string, string> {
  if (credentials.accessToken?.trim()) {
    return { Authorization: `Bearer ${credentials.accessToken}` };
  }
  if (credentials.builderApiKey?.trim()) {
    return { [BUILDER_API_KEY_HEADER]: credentials.builderApiKey };
  }
  return {};
}

/** Auth headers for api.build — canonical `X-Api-Key` only. */
export function builderApiKeyHeaders(builderApiKey: string): Record<string, string> {
  return requestAuthHeaders({ builderApiKey });
}
