import { buildBazaarClient } from "./bazaar.js";
import { anyAbortSignal } from "./abort.js";
import { parseUserIdFromAccessToken, parseHumanIdFromBuilderApiKey } from "./builder-key.js";
import { getLatestHistoryFingerprint } from "./history.js";
import {
  sanitizeMessageRecord,
  sanitizeMessagingPayload,
  sanitizeMind,
  sanitizeAwakenResult,
  sanitizeCognitionBalance,
} from "./sanitize.js";
import { requestJson, type RequestOpts } from "./http.js";
import { isReplyEvent } from "./reply.js";
import { readMessagingEventsStream, streamEvents } from "./sse.js";
import { requireAuth } from "./require-auth.js";
import type { ClientCredentials } from "./auth-headers.js";
import type {
  AccountCircle,
  AddCircleMembersBody,
  AwakenMindOptions,
  AwakenMindResult,
  BazaarClient,
  BuilderMind,
  CheckMindNameResult,
  CircleMember,
  CircleMutationResult,
  CognitionUsageByToolOptions,
  CognitionUsageByToolResponse,
  CognitionUsageOptions,
  CognitionUsageResponse,
  Conversation,
  CreateConversationBody,
  EquipAppResultItem,
  EquipIdsBody,
  EquipMutationResult,
  EquipSkillResultItem,
  EquippedApp,
  EquippedSkill,
  EventsIteratorOptions,
  GetHistoryOptions,
  ListMindsOptions,
  MessageRecord,
  MessagingEvent,
  CognitionBalance,
  MindsClientOptions,
  RemoveCircleMembersBody,
  SendMessageBody,
  SubscribeEventsOptions,
  Subscription,
  UpdateMindStatusBody,
  UpdateMindStatusResult,
  WaitForReplyOptions,
  WaitForReplyOutcome,
} from "./types.js";
import { API_BUILD_BASE_URL } from "./constants.js";
import { MindsApiError } from "./errors.js";

export interface MindsClient {
  readonly bazaar: BazaarClient;
  /** Set or clear the OAuth access token. Empty/null falls back to the Builder API key. */
  setAccessToken(accessToken: string | null): void;
  listMinds(opts?: ListMindsOptions): Promise<BuilderMind[]>;
  createConversation(body: CreateConversationBody): Promise<Conversation>;
  listConversations(): Promise<Conversation[]>;
  getConversation(alias: string): Promise<Conversation>;
  sendMessage(body: SendMessageBody): Promise<Record<string, unknown>>;
  getHistory(alias: string, opts?: GetHistoryOptions): Promise<MessageRecord[]>;
  getLatestHistoryFingerprint(alias: string, signal?: AbortSignal): Promise<string | undefined>;
  subscribeEvents(opts: SubscribeEventsOptions): Subscription;
  eventsIterator(opts: EventsIteratorOptions): AsyncGenerator<MessagingEvent>;
  waitForReply(opts: WaitForReplyOptions): Promise<WaitForReplyOutcome>;
  ensureConversation(alias: string, mindId: string): Promise<Conversation>;
  getMindIdForAlias(alias: string): Promise<string | undefined>;
  getCognitionUsage(mindId: string, opts?: CognitionUsageOptions): Promise<CognitionUsageResponse>;
  getCognitionUsageByTool(
    mindId: string,
    opts?: CognitionUsageByToolOptions,
  ): Promise<CognitionUsageByToolResponse>;
  getMind(mindId: string, signal?: AbortSignal): Promise<BuilderMind>;
  checkMindName(name: string, signal?: AbortSignal): Promise<CheckMindNameResult>;
  awakenMind(opts: AwakenMindOptions): Promise<AwakenMindResult>;
  getCognitionBalance(mindId: string, signal?: AbortSignal): Promise<CognitionBalance>;
  updateMindStatus(mindId: string, body: UpdateMindStatusBody): Promise<UpdateMindStatusResult>;
  listEquippedSkills(mindId: string, signal?: AbortSignal): Promise<EquippedSkill[]>;
  equipSkills(
    mindId: string,
    body: EquipIdsBody,
  ): Promise<EquipMutationResult<EquipSkillResultItem>>;
  unequipSkills(
    mindId: string,
    body: EquipIdsBody,
  ): Promise<EquipMutationResult<EquipSkillResultItem>>;
  listEquippedApps(mindId: string, signal?: AbortSignal): Promise<EquippedApp[]>;
  equipApps(mindId: string, body: EquipIdsBody): Promise<EquipMutationResult<EquipAppResultItem>>;
  unequipApps(mindId: string, body: EquipIdsBody): Promise<EquipMutationResult<EquipAppResultItem>>;
  getCircle(mindId: string, signal?: AbortSignal): Promise<CircleMember[]>;
  addCircleMembers(mindId: string, body: AddCircleMembersBody): Promise<CircleMutationResult>;
  removeCircleMembers(mindId: string, body: RemoveCircleMembersBody): Promise<CircleMutationResult>;
  listCirclesForAccount(opts?: ListMindsOptions): Promise<AccountCircle[]>;
}

/** @internal Vitest and monorepo scripts only — not exported from package entry. */
export interface BuildMindsClientDeps {
  builderApiKey?: string;
  accessToken?: string;
  getAccessToken?: () => Promise<string | null>;
  baseUrl: string;
  fetchImpl: typeof fetch;
}

/** @internal */
export function buildMindsClient(deps: BuildMindsClientDeps): MindsClient {
  const baseUrl = deps.baseUrl.replace(/\/$/, "");
  const credentials: ClientCredentials = {
    ...(deps.builderApiKey !== undefined ? { builderApiKey: deps.builderApiKey } : {}),
    ...(deps.accessToken !== undefined ? { accessToken: deps.accessToken } : {}),
  };
  const fetchImpl = deps.fetchImpl;
  const getAccessToken = deps.getAccessToken;

  /** Resolve Bearer for this request; factory token wins over static accessToken. */
  const resolveCredentials = async (): Promise<ClientCredentials> => {
    if (!getAccessToken) return { ...credentials };
    const token = await getAccessToken();
    const trimmed = token?.trim();
    if (trimmed) {
      return {
        ...(credentials.builderApiKey !== undefined
          ? { builderApiKey: credentials.builderApiKey }
          : {}),
        accessToken: trimmed,
      };
    }
    return { ...credentials };
  };

  const authReq = async <T>(path: string, opts?: RequestOpts) => {
    const creds = await resolveCredentials();
    requireAuth(creds);
    return requestJson<T>({
      baseUrl,
      ...creds,
      path,
      fetchImpl,
      ...(opts !== undefined ? { opts } : {}),
    });
  };

  const bazaar = buildBazaarClient({
    baseUrl,
    fetchImpl,
    credentials,
  });

  return {
    bazaar,

    setAccessToken(accessToken: string | null) {
      const trimmed = accessToken?.trim();
      if (trimmed) {
        credentials.accessToken = trimmed;
      } else {
        delete credentials.accessToken;
      }
    },

    async listMinds(opts) {
      const creds = await resolveCredentials();
      requireAuth(creds);

      let path: string | undefined;
      if (opts?.humanId) {
        path = `/v1/humans/${encodeURIComponent(opts.humanId)}/minds`;
      } else if (creds.accessToken) {
        const userId = parseUserIdFromAccessToken(creds.accessToken);
        if (userId) path = `/v1/users/${encodeURIComponent(userId)}/minds`;
      } else if (creds.builderApiKey) {
        const humanId = parseHumanIdFromBuilderApiKey(creds.builderApiKey);
        if (humanId) path = `/v1/humans/${encodeURIComponent(humanId)}/minds`;
      }

      if (!path) {
        throw new MindsApiError({
          status: 400,
          code: "missing_human_id",
          message:
            "Could not read userId from the access token or humanId from the Builder API key. Pass listMinds({ userId }) or listMinds({ humanId }) explicitly.",
        });
      }

      const rows = await authReq<Record<string, unknown>[]>(path, {
        retry502: true,
        ...(opts?.signal !== undefined ? { signal: opts.signal } : {}),
      });
      return rows.map((row) => sanitizeMind(row));
    },

    async createConversation(body) {
      return authReq<Conversation>("/v1/messaging/conversation", {
        method: "POST",
        body,
      });
    },

    async listConversations() {
      return authReq<Conversation[]>("/v1/messaging/conversations", { retry502: true });
    },

    async getConversation(alias) {
      return authReq<Conversation>(`/v1/messaging/conversations/${encodeURIComponent(alias)}`, {
        retry502: true,
      });
    },

    async sendMessage(body) {
      const message = await authReq<Record<string, unknown>>("/v1/messaging/message", {
        method: "POST",
        body,
        retry409: true,
      });
      return sanitizeMessagingPayload(message);
    },

    async getHistory(alias, opts) {
      // /histories is newest-first; the working pagination cursor is `before`.
      const cursor = opts?.cursor ?? opts?.after;
      const items = await authReq<MessageRecord[]>(
        `/v1/messaging/histories/${encodeURIComponent(alias)}`,
        {
          query: {
            ...(opts?.limit !== undefined ? { limit: opts.limit } : {}),
            ...(cursor !== undefined ? { before: cursor } : {}),
          },
          retry502: true,
          ...(opts?.signal !== undefined ? { signal: opts.signal } : {}),
        },
      );
      return items.map(sanitizeMessageRecord);
    },

    async getLatestHistoryFingerprint(alias, signal) {
      // Fetch pages directly so oldest-first walk can still use wire `after`
      // without going through getHistory's cursor→`before` mapping.
      return getLatestHistoryFingerprint(async (wire) => {
        const items = await authReq<MessageRecord[]>(
          `/v1/messaging/histories/${encodeURIComponent(alias)}`,
          {
            query: {
              limit: 200,
              ...(wire?.after !== undefined ? { after: wire.after } : {}),
            },
            retry502: true,
            ...(signal !== undefined ? { signal } : {}),
          },
        );
        return items.map(sanitizeMessageRecord);
      });
    },

    subscribeEvents(opts) {
      if (!getAccessToken) requireAuth(credentials);
      const { close, done } = readMessagingEventsStream({
        baseUrl,
        ...credentials,
        ...(getAccessToken !== undefined ? { getAccessToken } : {}),
        fetchImpl,
        ...(opts.alias !== undefined ? { alias: opts.alias } : {}),
        ...(opts.signal !== undefined ? { signal: opts.signal } : {}),
        onEvent: opts.onEvent,
        ...(opts.onError !== undefined ? { onError: opts.onError } : {}),
      });
      void done;
      return { close };
    },

    eventsIterator(opts) {
      if (!getAccessToken) requireAuth(credentials);
      return streamEvents({
        baseUrl,
        ...credentials,
        ...(getAccessToken !== undefined ? { getAccessToken } : {}),
        fetchImpl,
        alias: opts.alias,
        signal: opts.signal,
      });
    },

    async waitForReply(opts) {
      if (!getAccessToken) requireAuth(credentials);
      else requireAuth(await resolveCredentials());
      const ctx = {
        alias: opts.alias,
        afterFingerprint: opts.afterFingerprint,
        sentMessageText: opts.sentMessageText,
      };
      const deadline = Date.now() + opts.timeoutMs;
      const remaining = (): number => Math.max(0, deadline - Date.now());

      // Abort SSE at timeoutMs even when only heartbeats arrive (they do not yield events).
      const streamSignal = anyAbortSignal(opts.signal, AbortSignal.timeout(opts.timeoutMs));

      try {
        for await (const event of streamEvents({
          baseUrl,
          ...credentials,
          ...(getAccessToken !== undefined ? { getAccessToken } : {}),
          fetchImpl,
          alias: opts.alias,
          signal: streamSignal,
        })) {
          if (isReplyEvent(event, ctx)) {
            return { reply: event, timedOut: false };
          }
          if (remaining() <= 0) break;
        }
      } catch {
        /* fall through to history poll */
      }

      // Always poll at least once after SSE ends — reply may exist only in history when
      // the stream stayed open on heartbeats until the deadline.
      let historyPasses = 0;
      while (remaining() > 0 || historyPasses === 0) {
        if (opts.signal?.aborted) {
          return { timedOut: true };
        }
        historyPasses++;
        // Fetch the newest window (no cursor). /histories ignores `after` and
        // `before` would move toward older rows — client-side isReplyEvent +
        // afterFingerprint filters stale replies.
        const history = await this.getHistory(opts.alias, {
          limit: 50,
          ...(opts.signal !== undefined ? { signal: opts.signal } : {}),
        });
        for (const row of history) {
          if (isReplyEvent(row, ctx)) {
            return { reply: row, timedOut: false };
          }
        }
        if (remaining() <= 0) break;
        await new Promise((r) => setTimeout(r, Math.min(2000, remaining())));
      }

      return { timedOut: true };
    },

    async ensureConversation(alias, mindId) {
      try {
        return await this.createConversation({ alias, mindId });
      } catch (err) {
        if (!(err instanceof MindsApiError) || (err.status !== 409 && err.status !== 400)) {
          throw err;
        }
        const existing = await this.getConversation(alias);
        const existingMindId = typeof existing.mindId === "string" ? existing.mindId : undefined;
        if (existingMindId && existingMindId !== mindId) {
          throw new MindsApiError({
            status: 409,
            code: "alias_mind_mismatch",
            message: `Alias "${alias}" is bound to a different Mind.`,
          });
        }
        return existing;
      }
    },

    async getMindIdForAlias(alias) {
      try {
        const conversation = await this.getConversation(alias);
        if (typeof conversation.mindId === "string" && conversation.mindId) {
          return conversation.mindId;
        }
      } catch {
        /* fall through to history */
      }
      const rows = await this.getHistory(alias, { limit: 50 });
      // /histories is newest-first — scan from index 0 so we bind the latest Mind.
      for (const row of rows) {
        if (typeof row.mindId === "string" && row.mindId) return row.mindId;
        if (
          (row.senderType === 0 || row.senderType === 2) &&
          typeof row.senderId === "string" &&
          row.senderId
        ) {
          return row.senderId;
        }
      }
      return undefined;
    },

    async getCognitionUsage(mindId, opts) {
      return authReq<CognitionUsageResponse>(
        `/v1/minds/${encodeURIComponent(mindId)}/cognition/usage`,
        {
          query: {
            ...(opts?.interval !== undefined ? { interval: opts.interval } : {}),
            ...(opts?.startTime !== undefined ? { startTime: opts.startTime } : {}),
            ...(opts?.endTime !== undefined ? { endTime: opts.endTime } : {}),
          },
          retry502: true,
          ...(opts?.signal !== undefined ? { signal: opts.signal } : {}),
        },
      );
    },

    async getCognitionUsageByTool(mindId, opts) {
      return authReq<CognitionUsageByToolResponse>(
        `/v1/minds/${encodeURIComponent(mindId)}/cognition/usage-by-tool`,
        {
          query: {
            ...(opts?.interval !== undefined ? { interval: opts.interval } : {}),
            ...(opts?.startTime !== undefined ? { startTime: opts.startTime } : {}),
            ...(opts?.endTime !== undefined ? { endTime: opts.endTime } : {}),
          },
          retry502: true,
          ...(opts?.signal !== undefined ? { signal: opts.signal } : {}),
        },
      );
    },

    async getMind(mindId, signal) {
      const raw = await authReq<Record<string, unknown>>(
        `/v1/minds/${encodeURIComponent(mindId)}`,
        {
          retry502: true,
          ...(signal !== undefined ? { signal } : {}),
        },
      );
      return sanitizeMind(raw);
    },

    async checkMindName(name, signal) {
      const raw = await requestJson<CheckMindNameResult & { available?: boolean }>({
        baseUrl,
        fetchImpl,
        path: "/v1/minds/check/name",
        ...credentials,
        opts: {
          query: { name },
          retry502: true,
          ...(signal !== undefined ? { signal } : {}),
        },
      });
      return {
        ...raw,
        isAvailable: raw.isAvailable === true || raw.available === true,
      };
    },

    async awakenMind(opts) {
      const body: Record<string, unknown> = {
        id: opts.id,
        mindName: opts.name,
      };
      if (opts.language !== undefined) body.language = opts.language;
      if (opts.species !== undefined) body.species = opts.species;
      const raw = await authReq<Record<string, unknown>>("/v1/minds/awaken", {
        method: "POST",
        body,
        ...(opts.signal !== undefined ? { signal: opts.signal } : {}),
      });
      return sanitizeAwakenResult(raw);
    },

    async getCognitionBalance(mindId, signal) {
      const raw = await authReq<Record<string, unknown>>(
        `/v1/minds/${encodeURIComponent(mindId)}/credits`,
        {
          retry502: true,
          ...(signal !== undefined ? { signal } : {}),
        },
      );
      return sanitizeCognitionBalance(raw);
    },

    async updateMindStatus(mindId, body) {
      const raw = await authReq<Record<string, unknown>>(
        `/v1/minds/${encodeURIComponent(mindId)}`,
        {
          method: "PATCH",
          body,
        },
      );
      return {
        msg: typeof raw.msg === "string" ? raw.msg : null,
        result: typeof raw.result === "string" ? raw.result : null,
      };
    },

    async listEquippedSkills(mindId, signal) {
      return authReq<EquippedSkill[]>(`/v1/minds/${encodeURIComponent(mindId)}/skills`, {
        retry502: true,
        ...(signal !== undefined ? { signal } : {}),
      });
    },

    async equipSkills(mindId, body) {
      return authReq<EquipMutationResult<EquipSkillResultItem>>(
        `/v1/minds/${encodeURIComponent(mindId)}/skills`,
        { method: "PUT", body },
      );
    },

    async unequipSkills(mindId, body) {
      return authReq<EquipMutationResult<EquipSkillResultItem>>(
        `/v1/minds/${encodeURIComponent(mindId)}/skills`,
        { method: "DELETE", body },
      );
    },

    async listEquippedApps(mindId, signal) {
      return authReq<EquippedApp[]>(`/v1/minds/${encodeURIComponent(mindId)}/apps`, {
        retry502: true,
        ...(signal !== undefined ? { signal } : {}),
      });
    },

    async equipApps(mindId, body) {
      return authReq<EquipMutationResult<EquipAppResultItem>>(
        `/v1/minds/${encodeURIComponent(mindId)}/apps`,
        { method: "PUT", body },
      );
    },

    async unequipApps(mindId, body) {
      return authReq<EquipMutationResult<EquipAppResultItem>>(
        `/v1/minds/${encodeURIComponent(mindId)}/apps`,
        { method: "DELETE", body },
      );
    },

    async getCircle(mindId, signal) {
      return authReq<CircleMember[]>(`/v1/circles/${encodeURIComponent(mindId)}`, {
        retry502: true,
        ...(signal !== undefined ? { signal } : {}),
      });
    },

    async addCircleMembers(mindId, body) {
      return authReq<CircleMutationResult>(`/v1/circles/${encodeURIComponent(mindId)}`, {
        method: "POST",
        body,
      });
    },

    async removeCircleMembers(mindId, body) {
      return authReq<CircleMutationResult>(`/v1/circles/${encodeURIComponent(mindId)}`, {
        method: "DELETE",
        body,
      });
    },

    async listCirclesForAccount(opts) {
      const minds = await this.listMinds(opts);
      return Promise.all(
        minds.map(async (mind) => {
          const members = await this.getCircle(mind.mindId, opts?.signal);
          return {
            mindId: mind.mindId,
            name: mind.name,
            members,
          };
        }),
      );
    },
  };
}

export function createMindsClient(options: MindsClientOptions = {}): MindsClient {
  return buildMindsClient({
    ...(options.builderApiKey !== undefined ? { builderApiKey: options.builderApiKey } : {}),
    ...(options.accessToken !== undefined ? { accessToken: options.accessToken } : {}),
    ...(options.getAccessToken !== undefined ? { getAccessToken: options.getAccessToken } : {}),
    baseUrl: API_BUILD_BASE_URL,
    fetchImpl: (input, init) => globalThis.fetch(input, init),
  });
}
