import type { BuilderMind, CognitionBalance, MessageRecord } from "./types.js";

/** Platform-internal conversation subject — omitted from SDK and CLI output. */
export const INTERNAL_MESSAGE_SUBJECT = "#moca#";

/**
 * Normalize messaging payloads for the public SDK contract:
 * - map wire `partyType` → `senderType` (SSE still uses partyType)
 * - strip `partyType` so callers only see `senderType`
 * - omit internal `#moca#` subject
 */
export function sanitizeMessageRecord<T extends MessageRecord>(record: T): T {
  const raw = record as MessageRecord & { partyType?: number | null };
  const next: Record<string, unknown> = { ...raw };

  if (next.senderType == null && typeof raw.partyType === "number") {
    next.senderType = raw.partyType;
  }
  delete next.partyType;

  if (next.subject === INTERNAL_MESSAGE_SUBJECT) {
    delete next.subject;
  }

  return next as T;
}

export function sanitizeMessagingPayload<T extends Record<string, unknown>>(payload: T): T {
  if (payload.subject !== INTERNAL_MESSAGE_SUBJECT) return payload;
  const { subject: _omit, ...rest } = payload;
  return rest as T;
}

/** Map platform credits payload to builder-facing `{ mindId, cognition }` only. */
export function sanitizeCognitionBalance(data: Record<string, unknown>): CognitionBalance {
  const mindId = String(data.mindId ?? "");
  const cognition = typeof data.swarm === "number" ? data.swarm : 0;
  // Drops platform fields (credits, creditsMinted, creditsStaged, num, …).
  return { mindId, cognition };
}

const CHAIN_OBJECT_KEYS = ["name", "slug", "chain", "chainId", "id"] as const;

function coerceStringScalar(value: unknown): string | null {
  if (typeof value === "string" && value.length > 0) return value;
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  return null;
}

function coerceChainObject(value: Record<string, unknown>): string | null {
  for (const key of CHAIN_OBJECT_KEYS) {
    const scalar = coerceStringScalar(value[key]);
    if (scalar) return scalar;
  }
  return null;
}

function coerceWalletAddress(raw: unknown): string | null {
  if (Array.isArray(raw)) {
    for (const item of raw) {
      const scalar = coerceStringScalar(item);
      if (scalar) return scalar;
    }
    return null;
  }
  return coerceStringScalar(raw);
}

function coerceChain(raw: unknown): string | null {
  if (Array.isArray(raw)) {
    for (const item of raw) {
      if (typeof item === "string" || typeof item === "number") {
        const scalar = coerceStringScalar(item);
        if (scalar) return scalar;
      }
      if (item && typeof item === "object") {
        const scalar = coerceChainObject(item as Record<string, unknown>);
        if (scalar) return scalar;
      }
    }
    return null;
  }
  if (raw && typeof raw === "object") {
    return coerceChainObject(raw as Record<string, unknown>);
  }
  return coerceStringScalar(raw);
}

/** Map platform Mind payload to builder-facing singular wallet and chain fields. */
export function sanitizeMind(data: Record<string, unknown>): BuilderMind {
  const hasWalletField = "walletAddresses" in data || "walletAddress" in data;
  const hasChainField = "chains" in data || "chain" in data;
  const walletAddress = hasWalletField
    ? coerceWalletAddress(data.walletAddresses ?? data.walletAddress)
    : undefined;
  const chain = hasChainField ? coerceChain(data.chains ?? data.chain) : undefined;

  const {
    walletAddresses: _walletAddresses,
    chains: _chains,
    walletAddress: _walletAddress,
    chain: _chain,
    ...rest
  } = data;

  return {
    ...rest,
    ...(hasWalletField ? { walletAddress: walletAddress ?? null } : {}),
    ...(hasChainField ? { chain: chain ?? null } : {}),
  } as BuilderMind;
}

/** Map awaken/create payloads that use `mindName` / `mindEmail` onto BuilderMind fields. */
export function sanitizeAwakenResult(data: Record<string, unknown>): BuilderMind {
  const mind = sanitizeMind(data);
  const name =
    typeof mind.name === "string" && mind.name.length > 0
      ? mind.name
      : typeof data.mindName === "string"
        ? data.mindName
        : mind.name;
  const email =
    typeof mind.email === "string" && mind.email.length > 0
      ? mind.email
      : typeof data.mindEmail === "string"
        ? data.mindEmail
        : mind.email;
  return {
    ...mind,
    ...(name !== undefined ? { name } : {}),
    ...(email !== undefined ? { email } : {}),
  };
}
