import { MindsApiError } from "./errors.js";
import type { ClientCredentials } from "./auth-headers.js";

/** @internal */
export function requireAuth(credentials: ClientCredentials): void {
  if (credentials.accessToken?.trim() || credentials.builderApiKey?.trim()) return;
  throw new MindsApiError({
    status: 401,
    // Backward-compatible client error code; access tokens are now also accepted.
    code: "missing_builder_api_key",
    message:
      "An access token or Builder API key is required for this operation. Pass createMindsClient({ accessToken }) or createMindsClient({ builderApiKey }). Browser Connect apps should use createMindsClient({ getAccessToken }) after sign-in.",
  });
}
