import { decodeJwtPayload } from "./jwt-payload.js";

/** Builder API keys are JWTs with a `humanId` claim used for account routes. */
export function parseHumanIdFromBuilderApiKey(builderApiKey: string): string | undefined {
  const humanId = decodeJwtPayload(builderApiKey)?.humanId;
  return typeof humanId === "string" && humanId.length ? humanId : undefined;
}

/** OAuth access tokens mint `sub` as the account userId (UUID). */
export function parseUserIdFromAccessToken(accessToken: string): string | undefined {
  const subject = decodeJwtPayload(accessToken)?.sub;
  return typeof subject === "string" && subject.length ? subject : undefined;
}
