import { requestAuthHeaders } from "./auth-headers.js";
import { MindsApiError, errorFromResponse, parseErrorBody } from "./errors.js";

export type HttpMethod = "GET" | "POST" | "PUT" | "PATCH" | "DELETE";

export interface RequestOpts {
  method?: HttpMethod;
  body?: unknown;
  query?: Record<string, string | number | undefined>;
  signal?: AbortSignal;
  accept?: string;
  retry409?: boolean;
  retry502?: boolean;
}

export const RETRY_DELAYS_MS = [200, 400, 800] as const;
const GET_RETRY_DELAYS_MS = [300, 600] as const;

const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

export function buildUrl(
  base: string,
  path: string,
  query?: Record<string, string | number | undefined>,
): string {
  const url = new URL(path, base.endsWith("/") ? base : `${base}/`);
  if (path.startsWith("/")) url.pathname = path;
  if (query) {
    for (const [k, v] of Object.entries(query)) {
      if (v === undefined) continue;
      url.searchParams.set(k, String(v));
    }
  }
  return url.toString();
}

export async function requestJson<T>(args: {
  baseUrl: string;
  builderApiKey?: string;
  accessToken?: string;
  path: string;
  fetchImpl: typeof fetch;
  opts?: RequestOpts;
}): Promise<T> {
  const opts = args.opts ?? {};
  const url = buildUrl(args.baseUrl, args.path, opts.query);
  const method = opts.method ?? "GET";
  const headers: Record<string, string> = {
    Accept: opts.accept ?? "application/json",
    ...requestAuthHeaders({
      ...(args.accessToken !== undefined ? { accessToken: args.accessToken } : {}),
      ...(args.builderApiKey !== undefined ? { builderApiKey: args.builderApiKey } : {}),
    }),
  };
  const body = opts.body !== undefined ? JSON.stringify(opts.body) : undefined;
  if (body !== undefined) headers["Content-Type"] = "application/json";

  const retryDelays = opts.retry409 ? RETRY_DELAYS_MS : opts.retry502 ? GET_RETRY_DELAYS_MS : [];
  const attempts = retryDelays.length + 1;

  let lastErr: MindsApiError | undefined;
  for (let attempt = 0; attempt < attempts; attempt++) {
    let res: Response;
    try {
      const init: RequestInit = { method, headers };
      if (body !== undefined) init.body = body;
      if (opts.signal) init.signal = opts.signal;
      res = await args.fetchImpl(url, init);
    } catch (err) {
      throw new MindsApiError({
        status: 0,
        code: "network_error",
        message: `Network error: ${(err as Error).message}`,
      });
    }

    if (res.ok) {
      const ct = res.headers.get("content-type") ?? "";
      if (res.status === 204) return undefined as T;
      if (ct.includes("application/json")) return (await res.json()) as T;
      return (await res.text()) as unknown as T;
    }

    const errBody = parseErrorBody(await res.text());
    lastErr = errorFromResponse(res.status, errBody);

    const retry409 = res.status === 409 && opts.retry409;
    const retry502 = res.status === 502 && opts.retry502;
    if (!retry409 && !retry502) break;
    const delay = retryDelays[attempt];
    if (delay === undefined) break;
    await sleep(delay);
  }

  throw (
    lastErr ??
    new MindsApiError({
      status: 0,
      code: "unknown_error",
      message: "Request failed",
    })
  );
}
