import type { ClientCredentials } from "./auth-headers.js";
import { requestJson } from "./http.js";
import type {
  BazaarApp,
  BazaarClient,
  BazaarListResponse,
  BazaarSkill,
  BazaarSort,
  CollectBazaarSearchOptions,
  CollectBazaarSearchResult,
} from "./types.js";

export interface BuildBazaarDeps {
  baseUrl: string;
  credentials?: ClientCredentials;
  fetchImpl: typeof fetch;
}

function sortBazaarItems<T>(
  items: T[],
  sort: BazaarSort,
  getEquippedCount: (item: T) => number,
  getName: (item: T) => string,
  getCreatedAt: (item: T) => string | undefined,
): T[] {
  const copy = [...items];
  switch (sort) {
    case "equipped":
      copy.sort((a, b) => getEquippedCount(b) - getEquippedCount(a));
      break;
    case "name":
      copy.sort((a, b) => getName(a).localeCompare(getName(b)));
      break;
    case "newest":
      copy.sort((a, b) => {
        const aTime = getCreatedAt(a) ?? "";
        const bTime = getCreatedAt(b) ?? "";
        return bTime.localeCompare(aTime);
      });
      break;
  }
  return copy;
}

async function collectSearchResults<T>(
  opts: CollectBazaarSearchOptions<T>,
): Promise<CollectBazaarSearchResult<T>> {
  const pageSize = Math.min(100, opts.scanMax);
  const allItems: T[] = [];
  let totalCount = 0;
  let page = 1;

  while (allItems.length < opts.scanMax) {
    const response = await opts.fetchPage(page, pageSize);
    totalCount = response.totalCount;
    allItems.push(...response.items);

    const target = Math.min(totalCount, opts.scanMax);
    if (allItems.length >= target) break;
    if (response.items.length === 0 || response.items.length < pageSize) break;
    page++;
  }

  const scanned = allItems.length;
  const filtered = opts.filter ? allItems.filter(opts.filter) : allItems;
  const matchedAfterFilter = filtered.length;
  const sorted = sortBazaarItems(
    filtered,
    opts.sort,
    opts.getEquippedCount,
    opts.getName,
    opts.getCreatedAt,
  );
  const items = sorted.slice(0, opts.max);
  const returned = items.length;
  const truncated = totalCount > scanned || matchedAfterFilter > returned;

  return { totalCount, scanned, returned, truncated, items };
}

/** @internal */
export function buildBazaarClient(deps: BuildBazaarDeps): BazaarClient {
  const baseUrl = deps.baseUrl.replace(/\/$/, "");
  const credentials = deps.credentials ?? {};
  const { fetchImpl } = deps;

  const req = <T>(path: string, opts?: Parameters<typeof requestJson>[0]["opts"]) =>
    requestJson<T>({
      baseUrl,
      ...credentials,
      path,
      fetchImpl,
      ...(opts !== undefined ? { opts } : {}),
    });

  return {
    listSkills(opts) {
      return req<BazaarListResponse<BazaarSkill>>("/v1/bazaar/skills", {
        query: {
          ...(opts?.search !== undefined ? { search: opts.search } : {}),
          ...(opts?.page !== undefined ? { page: opts.page } : {}),
          ...(opts?.pageSize !== undefined ? { pageSize: opts.pageSize } : {}),
        },
        retry502: true,
        ...(opts?.signal !== undefined ? { signal: opts.signal } : {}),
      });
    },

    getSkill(skillId, signal) {
      return req<BazaarSkill>(`/v1/bazaar/skills/${encodeURIComponent(skillId)}`, {
        retry502: true,
        ...(signal !== undefined ? { signal } : {}),
      });
    },

    listApps(opts) {
      return req<BazaarListResponse<BazaarApp>>("/v1/bazaar/apps", {
        query: {
          ...(opts?.search !== undefined ? { search: opts.search } : {}),
          ...(opts?.tier !== undefined ? { tier: opts.tier } : {}),
          ...(opts?.page !== undefined ? { page: opts.page } : {}),
          ...(opts?.pageSize !== undefined ? { pageSize: opts.pageSize } : {}),
        },
        retry502: true,
        ...(opts?.signal !== undefined ? { signal: opts.signal } : {}),
      });
    },

    getApp(appId, signal) {
      return req<BazaarApp>(`/v1/bazaar/apps/${encodeURIComponent(appId)}`, {
        retry502: true,
        ...(signal !== undefined ? { signal } : {}),
      });
    },

    collectSearchResults,
  };
}
