import type { MessageRecord } from "./types.js";

const HISTORY_PAGE_SIZE = 200;

/** Wire options for a single history page fetch used by {@link getLatestHistoryFingerprint}. */
export type HistoryFingerprintPageWire = {
  /** Oldest-first feeds only — exclusive lower bound (`after` query param). */
  after?: string;
};

function maxFingerprint(rows: MessageRecord[]): string | undefined {
  let latest: string | undefined;
  for (const row of rows) {
    const fp = row.fingerprint;
    if (fp !== undefined && fp.length > 0 && (latest === undefined || fp > latest)) {
      latest = fp;
    }
  }
  return latest;
}

/**
 * Newest fingerprint in the transcript.
 *
 * `/v1/messaging/histories/{alias}` returns **newest-first**, so the first page
 * already contains the latest row — take the max fingerprint (time-prefixed),
 * not `page[page.length - 1]`.
 *
 * Still supports oldest-first pages by walking forward with `after` when a full
 * page is ascending.
 */
export async function getLatestHistoryFingerprint(
  fetchPage: (wire: HistoryFingerprintPageWire | undefined) => Promise<MessageRecord[]>,
): Promise<string | undefined> {
  const page = await fetchPage(undefined);
  if (page.length === 0) return undefined;

  let latest = maxFingerprint(page);
  if (latest === undefined) return undefined;

  const first = page[0]?.fingerprint;
  const last = page[page.length - 1]?.fingerprint;
  const oldestFirst = typeof first === "string" && typeof last === "string" && first < last;

  // Newest-first (or short page): first response already includes the newest row.
  if (!oldestFirst || page.length < HISTORY_PAGE_SIZE) {
    return latest;
  }

  // Oldest-first full page: walk forward until a short page (or a stuck cursor).
  let after = last;
  for (;;) {
    const next = await fetchPage({ after });
    if (next.length === 0) break;
    const nextLatest = maxFingerprint(next);
    if (nextLatest !== undefined && nextLatest > latest) {
      latest = nextLatest;
    }
    const nextLast = next[next.length - 1]?.fingerprint;
    if (next.length < HISTORY_PAGE_SIZE || nextLast === undefined || nextLast === after) {
      break;
    }
    after = nextLast;
  }

  return latest;
}
